/* Базовые стили — для МОБИЛЬНЫХ (по умолчанию) */
.container {
  padding: 10px;
}

.card {
  width: 100%;
}

/* Добавляем стили для ПЛАНШЕТОВ */
@media (min-width: 768px) {
  .container {
    padding: 20px;
  }
  .card {
    width: 50%;
  }
}

/* Добавляем стили для ДЕСКТОПОВ */
@media (min-width: 1024px) {
  .container {
    padding: 40px;
  }
  .card {
    width: 33.33%;
  }
}

/* Жидкий макет */
.container {
  width: 90%;      /* 90% ширины экрана */
  max-width: 1200px; /* но не шире 1200px */
  margin: 0 auto;    /* по центру */
}

.card {
  width: 50%;       /* половина контейнера */
  float: left;
}

/* Адаптивная карточка */
.card {
  width: 100%;          /* на всю ширину */
  max-width: 400px;     /* но не шире 400px */
  padding: 1.5rem;      /* отступы в rem */
  font-size: 1rem;      /* шрифт в rem */
}

/* Секция на весь экран */
.hero {
  height: 100vh;
  width: 100%;
}

/* Mobile-first: базовый размер */
h1 {
  font-size: 1.5rem;
}

/* Планшеты */
@media (min-width: 768px) {
  h1 {
    font-size: 2rem;
  }
}

/* Десктопы */
@media (min-width: 1024px) {
  h1 {
    font-size: 2.5rem;
  }
}

img {
  max-width: 100%;  /* не шире родителя */
  height: auto;     /* сохраняет пропорции */
}
